mapper.select:
select id, glue, segment, mother_glue1, mother_glue2, mother_glue3, mother_glue4, mother_glue5, mother_glue6, mother_glue7, mother_glue8, mother_glue9, remark, del_flag, create_by, create_time, update_by, update_time from t_glue_decompose where del_flag = '0' and INSTR(glue, #{glue}) > 0 and segment = #{segment}
order by create_time desc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.glue,jdbcType= VARCHAR} GLUE
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_glue_decompose m inner join temp_table t on m.GLUE = t.GLUE and m.del_flag ='0'

